// Custom controls keep their native input as the single source of truth.
let controlPopup=null,controlOwner=null,controlTrigger=null;
const controlArrow='<svg viewBox="0 0 20 20" aria-hidden="true"><path d="m5 7 5 5 5-5" fill="none" stroke="currentColor" stroke-width="1.6"/></svg>';
function closeControlPopup(focus=false){controlPopup?.remove();controlPopup=null;controlTrigger?.setAttribute('aria-expanded','false');if(focus&&controlTrigger?.isConnected)controlTrigger.focus();controlOwner=null;controlTrigger=null;}
function controlLabel(input){return input.getAttribute('aria-label')||input.closest('label')?.childNodes[0]?.textContent.trim()||input.name||'Выбор';}
function controlText(input){if(input.tagName==='SELECT')return input.selectedOptions[0]?.textContent||'Выберите';if(!input.value)return 'Выберите дату';const [date,time]=input.value.split('T');return date.split('-').reverse().join('.')+(time?' · '+time:'');}
function syncControl(input){const wrapper=input.closest('.ui-control');if(!wrapper)return;const trigger=wrapper.querySelector('.ui-control-trigger');const label=trigger.querySelector('span'),text=controlText(input);if(label.textContent!==text)label.textContent=text;trigger.disabled=input.disabled;trigger.setAttribute('aria-label',controlLabel(input)+': '+controlText(input));}
function placeControlPopup(){if(!controlPopup||!controlTrigger?.isConnected){closeControlPopup();return;}const r=controlTrigger.getBoundingClientRect(),width=Math.min(innerWidth-24,Math.max(r.width,controlOwner.tagName==='SELECT'?260:308));controlPopup.style.width=width+'px';const height=Math.min(controlPopup.scrollHeight,380,innerHeight-24);controlPopup.style.maxHeight=height+'px';controlPopup.style.left=Math.max(12,Math.min(r.left,innerWidth-width-12))+'px';controlPopup.style.top=Math.max(12,r.bottom+8+height>innerHeight?r.top-height-8:r.bottom+8)+'px';}
function commitControl(value){const input=controlOwner;const trigger=controlTrigger;input.value=value;closeControlPopup();syncControl(input);input.dispatchEvent(new Event('input',{bubbles:true}));input.dispatchEvent(new Event('change',{bubbles:true}));if(trigger.isConnected)trigger.focus();}
function openControl(input,trigger){closeControlPopup();controlOwner=input;controlTrigger=trigger;trigger.setAttribute('aria-expanded','true');const popup=document.createElement('div');popup.className='ui-control-popup';popup.setAttribute('role','dialog');popup.setAttribute('aria-label',controlLabel(input));controlPopup=popup;(input.closest('dialog')||document.body).append(popup);
 if(input.tagName==='SELECT'){
  popup.innerHTML=(input.options.length>7?'<input class="ui-option-search" type="search" placeholder="Найти в списке" aria-label="Поиск вариантов">':'')+'<div class="ui-options" role="listbox" aria-label="'+esc(controlLabel(input))+'"></div>';
  const list=popup.querySelector('.ui-options');const paint=()=>{const query=popup.querySelector('.ui-option-search')?.value.toLocaleLowerCase('ru')||'';list.innerHTML=[...input.options].filter(o=>o.text.toLocaleLowerCase('ru').includes(query)).map(o=>'<button type="button" role="option" aria-selected="'+o.selected+'" '+(o.disabled?'disabled':'')+' data-option="'+esc(o.value)+'"><span>'+esc(o.text)+'</span>'+(o.selected?'<span aria-hidden="true">✓</span>':'')+'</button>').join('')||'<p class="muted">Ничего не найдено</p>';};paint();popup.querySelector('.ui-option-search')?.addEventListener('input',paint);list.addEventListener('click',e=>{const b=e.target.closest('[data-option]');if(b&&!b.disabled)commitControl(b.dataset.option)});
  popup.addEventListener('keydown',e=>{const buttons=[...list.querySelectorAll('button:not(:disabled)')];if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();const i=buttons.indexOf(document.activeElement);buttons[e.key==='Home'?0:e.key==='End'?buttons.length-1:Math.max(0,Math.min(buttons.length-1,i+(e.key==='ArrowDown'?1:-1)))]?.focus({preventScroll:true});}});
  placeControlPopup();(popup.querySelector('.ui-option-search')||list.querySelector('[aria-selected=true]')||list.querySelector('button'))?.focus({preventScroll:true});
 }else{
  const initial=input.value.slice(0,10)||TODAY;let month=new Date(initial+'T12:00');let picked=initial;const datetime=input.type==='datetime-local';let time=input.value.split('T')[1]||'09:00';
  const draw=()=>{const first=new Date(month.getFullYear(),month.getMonth(),1,12),start=new Date(first);start.setDate(1-(first.getDay()+6)%7);const days=Array.from({length:42},(_,i)=>{const day=new Date(start);day.setDate(start.getDate()+i);const iso=day.toLocaleDateString('sv-SE');const disabled=input.min&&iso<input.min.slice(0,10)||input.max&&iso>input.max.slice(0,10);return '<button type="button" role="gridcell" data-day="'+iso+'" aria-label="'+day.toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'})+'" aria-selected="'+(iso===picked)+'" class="'+(day.getMonth()!==month.getMonth()?'other-month ':'')+(iso===TODAY?'today':'')+'" '+(disabled?'disabled':'')+'>'+day.getDate()+'</button>'}).join('');popup.innerHTML='<div class="ui-calendar-head"><button type="button" data-month="-1" aria-label="Предыдущий месяц">‹</button><strong>'+esc(month.toLocaleDateString('ru-RU',{month:'long',year:'numeric'}))+'</strong><button type="button" data-month="1" aria-label="Следующий месяц">›</button></div><div class="ui-calendar-week" aria-hidden="true">'+['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(d=>'<span>'+d+'</span>').join('')+'</div><div class="ui-calendar-days" role="grid" aria-label="Дни месяца">'+days+'</div>'+(datetime?'<label class="ui-calendar-time">Время<input type="time" value="'+esc(time)+'" aria-label="Время"></label>':'')+'<div class="ui-calendar-foot"><button type="button" data-today>Сегодня</button>'+(!input.required?'<button type="button" data-clear>Очистить</button>':'')+(datetime?'<button type="button" class="primary" data-apply>Выбрать</button>':'')+'</div>';placeControlPopup();};
  popup.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.month){month=new Date(month.getFullYear(),month.getMonth()+Number(b.dataset.month),1,12);draw();popup.querySelector('[data-month="'+b.dataset.month+'"]').focus();}else if(b.dataset.day){picked=b.dataset.day;if(datetime){draw();popup.querySelector('[data-day="'+picked+'"]').focus()}else commitControl(picked);}else if(b.hasAttribute('data-today')){if(input.min&&TODAY<input.min.slice(0,10)||input.max&&TODAY>input.max.slice(0,10))return;picked=TODAY;month=new Date(TODAY+'T12:00');if(datetime)draw();else commitControl(TODAY);}else if(b.hasAttribute('data-clear'))commitControl('');else if(b.hasAttribute('data-apply')){const value=picked+'T'+time;if(input.min&&value<input.min||input.max&&value>input.max){toast('Выберите дату и время в допустимом диапазоне');return}commitControl(value);}});
  popup.addEventListener('input',e=>{if(e.target.type==='time')time=e.target.value;});
  popup.addEventListener('keydown',e=>{if(!e.target.matches('[data-day]'))return;const offset={ArrowLeft:-1,ArrowRight:1,ArrowUp:-7,ArrowDown:7}[e.key];if(!offset)return;e.preventDefault();const d=new Date(e.target.dataset.day+'T12:00');d.setDate(d.getDate()+offset);const iso=d.toLocaleDateString('sv-SE');if(d.getMonth()!==month.getMonth()){month=new Date(d.getFullYear(),d.getMonth(),1,12);draw()}popup.querySelector('[data-day="'+iso+'"]:not(:disabled)')?.focus({preventScroll:true});});draw();popup.querySelector('[data-day="'+picked+'"]')?.focus({preventScroll:true});
 }
}
function enhanceControls(){document.querySelectorAll('select,input[type=date],input[type=datetime-local]').forEach(input=>{if(input.closest('.ui-control-popup'))return;if(input.closest('.ui-control')){syncControl(input);return;}const wrapper=document.createElement('span');wrapper.className='ui-control '+(input.tagName==='SELECT'?'ui-select':'ui-date');input.before(wrapper);wrapper.append(input);input.classList.add('ui-control-native');input.tabIndex=-1;input.setAttribute('aria-hidden','true');const trigger=document.createElement('button');trigger.type='button';trigger.className='ui-control-trigger';trigger.setAttribute('aria-haspopup','dialog');trigger.setAttribute('aria-expanded','false');trigger.innerHTML='<span></span>'+controlArrow;wrapper.append(trigger);syncControl(input);trigger.addEventListener('click',()=>controlOwner===input?closeControlPopup(true):openControl(input,trigger));trigger.addEventListener('keydown',e=>{if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();openControl(input,trigger)}});input.addEventListener('change',()=>syncControl(input));});if(controlOwner&&!controlOwner.isConnected)closeControlPopup();}
document.addEventListener('pointerdown',e=>{if(controlPopup&&!controlPopup.contains(e.target)&&!controlTrigger?.contains(e.target))closeControlPopup();});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&controlPopup){e.stopImmediatePropagation();e.preventDefault();closeControlPopup(true)}},true);
window.addEventListener('resize',()=>closeControlPopup());document.addEventListener('scroll',e=>{if(controlPopup&&!controlPopup.contains(e.target))placeControlPopup();},true);
let controlsQueued=false;new MutationObserver(()=>{if(controlsQueued)return;controlsQueued=true;requestAnimationFrame(()=>{controlsQueued=false;enhanceControls()});}).observe(document.body,{childList:true,subtree:true});enhanceControls();

// Remove the old footer after sidebar sections have initialized.
document.querySelector(".sidebar .sidefoot")?.remove();
